INSERT INTO public.system_changelog (version, title, description, change_type, affected_modules, is_public) VALUES ('6.18A-internal','Central de Implantacao e Ativacao de Clientes','Central de Implantacao para a equipe LLZ: estagio, percentual, proxima acao e nivel de atencao derivados exclusivamente de evidencias reais do banco. Inclui responsavel LLZ (sem vinculo empresarial), notas internas visiveis apenas para a equipe LLZ e validacao assistida. O percentual usa a mesma regra do checklist exibido ao cliente.','feature',ARRAY['implantacao','administracao','operacao'],false),('6.18A','Acompanhamento de implantacao de clientes','A plataforma passou a acompanhar a evolucao de implantacao dos clientes com etapas, progresso e indicadores baseados na operacao real.','feature',ARRAY['implantacao','administracao'],true),('6.18A.1-internal','Fechamento da Central de Implantacao','Empresa rejeitada passou a ter estagio proprio (Cadastro rejeitado), com KPI, filtro, atencao critica e proxima acao de revisao; deixou de aparecer como Aguardando aprovacao e nao entra na media de implantacao. O estagio artificial Cadastro recebido foi removido por ser inalcancavel no fluxo real. Adicionados testes unitarios da matriz de estagios e da fonte unica do checklist. Documentacao atualizada. Nenhuma regra de estoque, RLS ou RPC alterada.','fix',ARRAY['implantacao','administracao','documentacao'],false);